package com.machinefault.api.api;
import com.machinefault.api.api.ApiModels.*; import com.machinefault.api.domain.AppUser; import com.machinefault.api.domain.UserRole; import com.machinefault.api.repo.UserRepository; import com.machinefault.api.service.UserPresence; import jakarta.persistence.criteria.Predicate; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
// Account administration routes. The class-level rule protects every route below by default.
@RestController @RequestMapping("/api/users") @PreAuthorize("hasAuthority('SYSTEM_ADMINISTRATOR')") public class UserController {
 private final UserRepository users;private final PasswordEncoder passwords;public UserController(UserRepository u,PasswordEncoder p){users=u;passwords=p;}
 @GetMapping public Page<UserView> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(required=false) String search,@RequestParam(required=false) UserRole role,@RequestParam(required=false) Boolean enabled){if(page<0||size<1||size>100)throw new IllegalArgumentException("page must be >= 0 and size must be 1..100.");Specification<AppUser> filters=(root,query,cb)->{List<Predicate> predicates=new ArrayList<>();if(role!=null)predicates.add(cb.equal(root.get("role"),role));if(enabled!=null)predicates.add(cb.equal(root.get("enabled"),enabled));if(search!=null&&!search.isBlank()){String term="%"+search.trim().toLowerCase()+"%";predicates.add(cb.or(cb.like(cb.lower(root.get("username")),term),cb.like(cb.lower(root.get("displayName")),term),cb.like(cb.lower(root.get("email")),term)));}return cb.and(predicates.toArray(Predicate[]::new));};return users.findAll(filters,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"id"))).map(UserView::of);}
 @PostMapping public ResponseEntity<UserView> create(@Valid @RequestBody CreateUser body){if(users.findByUsername(body.username()).isPresent())throw new IllegalArgumentException("Username already exists.");if(users.findByEmail(body.email()).isPresent())throw new IllegalArgumentException("Email address already exists.");AppUser user=new AppUser(body.username(),body.displayName(),body.email(),passwords.encode(body.password()),body.role());user.setEnabled(body.enabled()==null||body.enabled());return ResponseEntity.status(201).body(UserView.of(users.save(user)));}
 @PatchMapping("/{id}") public UserView update(@PathVariable Long id,@Valid @RequestBody UpdateUser body){AppUser user=users.findById(id).orElseThrow(()->new NoSuchElementException("User not found."));users.findByEmail(body.email()).filter(existing->!existing.getId().equals(id)).ifPresent(existing->{throw new IllegalArgumentException("Email address already exists.");});user.updateProfile(body.displayName(),body.email(),body.role());return UserView.of(users.save(user));}
 @PatchMapping("/{id}/status") public UserView setStatus(@PathVariable Long id,@Valid @RequestBody ChangeUserStatus body){AppUser user=users.findById(id).orElseThrow(()->new NoSuchElementException("User not found."));user.setEnabled(body.enabled());return UserView.of(users.save(user));}
 @GetMapping("/technicians") @PreAuthorize("hasAnyAuthority('MAINTENANCE_SUPERVISOR','MAINTENANCE_MANAGER','SYSTEM_ADMINISTRATOR')") public List<UserView> technicians(){return users.findByRole(UserRole.MAINTENANCE_TECHNICIAN).stream().map(UserView::of).toList();}
}
